    local MB = Tab:AddRightGroupbox(__T["Safe Spot Guide"], "map")
    MB:AddToggle("mn_tracer", { Text = __T["Safe Spot Tracer"], Default = true, Tooltip = __T["Line to the nearest safe spot"] })
    MB:AddToggle("mn_label", { Text = __T["Distance Label"], Default = true })
    UI.mn = MB:AddLabel("", true)
