    tgt.Anchored, tgt.CanCollide, tgt.CanQuery, tgt.CanTouch, tgt.Transparency, tgt.Size = true, false, false, false, 1, Vector3.new(1, 1, 1)
    tgt.Parent = holder
    local a1 = Instance.new("Attachment", tgt)
    local beam = Instance.new("Beam")
    beam.Attachment1, beam.Width0, beam.Width1, beam.FaceCamera, beam.Segments = a1, 0.35, 0.35, true, 1
    beam.LightEmission, beam.Transparency = 1, NumberSequence.new(0.1)
    beam.Parent = holder
    local bb = Instance.new("BillboardGui")
    bb.Adornee, bb.AlwaysOnTop, bb.Size, bb.StudsOffset = tgt, true, UDim2.fromOffset(160, 36), Vector3.new(0, 2.5, 0)
    local tl = Instance.new("TextLabel")
    tl.BackgroundTransparency, tl.Size, tl.Font, tl.TextSize, tl.TextStrokeTransparency, tl.TextColor3 = 1, UDim2.fromScale(1, 1), Enum.Font.GothamBold, 14, 0.3, Color3.fromRGB(90, 230, 120)
    tl.Parent = bb
    pcall(function() bb.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
    if not bb.Parent then bb.Parent = lp:WaitForChild("PlayerGui") end
    onClean(function() pcall(function() bb:Destroy() end) end)
    local a0
    local GREEN, RED = Color3.fromRGB(90, 230, 120), Color3.fromRGB(255, 80, 80)
    task.spawn(function()
        while RUNNING do
            local r, h = G.root(), G.hum()
            local show = false
            UI.mnSpot = nil
            if on("mn_tracer") and r and h and h.Health > 0 and G.phase() == "Disaster" and G.inRound() and not on("sv_auto") then
                if not a0 or a0.Parent ~= r then if a0 then a0:Destroy() end a0 = Instance.new("Attachment") a0.Parent = r beam.Attachment0 = a0 end
                if AS.safeNow() and not lp:GetAttribute("Underwater") then
                    setText(UI.mn, __T["You are safe here"])
                else
                    local ok, s, why = pcall(AS.choose, r, h)
                    if ok and s then
                        UI.mnSpot = s.p
                        tgt.Position = s.p
                        local d = math.floor((s.p - r.Position).Magnitude)
                        tl.Text = __T["SAFE  "] .. d .. "m"
                        beam.Color = ColorSequence.new(GREEN)
                        setText(UI.mn, __T["Go to the line ("] .. d .. __T["m, "] .. tostring(why) .. ")")
                        show = true
                    else setText(UI.mn, __T["No safe spot found"]) end
                end
            else
                setText(UI.mn, on("sv_auto") and __T["Auto Survive is on"] or __T["Waiting for a disaster"])
            end
            beam.Enabled = show
            bb.Enabled = show and on("mn_label")
            task.wait(0.5)
        end
    end)
end)
section(__T["Fun"], function()
    local Tab = Window:AddTab(__T["Fun"], "zap")
    local MV = Tab:AddLeftGroupbox(__T["Movement"], "footprints")
    MV:AddToggle("fn_fly", { Text = __T["Fly"], Default = false }):AddKeyPicker("fn_fly_key", { Default = "F", Mode = "Toggle", Text = __T["Fly"], SyncToggleState = true })
    MV:AddSlider("fn_fly_s", { Text = __T["Fly Speed"], Default = 60, Min = 20, Max = 200, Rounding = 0 })
    MV:AddToggle("fn_noclip", { Text = __T["Noclip"], Default = false })
    MV:AddToggle("fn_ws", { Text = __T["Walk Speed"], Default = false, Callback = function(v) if not v then local h = G.hum() if h then h.WalkSpeed = 16 end end end })
    MV:AddSlider("fn_ws_v", { Text = __T["Speed"], Default = 32, Min = 16, Max = 100, Rounding = 0 })
    MV:AddToggle("fn_jp", { Text = __T["Jump Power"], Default = false, Callback = function(v) if not v then local h = G.hum() if h then h.UseJumpPower = true h.JumpPower = 50 end end end })
    MV:AddSlider("fn_jp_v", { Text = __T["Power"], Default = 80, Min = 50, Max = 250, Rounding = 0 })
    MV:AddToggle("fn_infjump", { Text = __T["Infinite Jump"], Default = false })
    MV:AddToggle("fn_clicktp", { Text = __T["Ctrl Click TP"], Default = false })
    local VH = Tab:AddRightGroupbox("Vehicles", "car")
    VH:AddToggle("fn_vfly", { Text = __T["Vehicle Fly"], Default = false, Tooltip = __T["W/S move, E/Q up/down, aim with camera"] })
    VH:AddSlider("fn_vfly_s", { Text = __T["Vehicle Fly Speed"], Default = 90, Min = 30, Max = 300, Rounding = 0 })
    VH:AddToggle("fn_vspeed", { Text = __T["Vehicle Speed Boost"], Default = false })
    VH:AddSlider("fn_vspeed_v", { Text = __T["Top Speed"], Default = 120, Min = 40, Max = 300, Rounding = 0 })
    VH:AddButton({ Text = __T["Enter Nearest Vehicle"], Func = function()
        local r, h = G.root(), G.hum()
        local m = G.map() local vf = m and m:FindFirstChild("Vehicles")
        if not (r and h and vf) then notify(__T["No vehicles here"]) return end
        local best, bd
        for _, d in ipairs(vf:GetDescendants()) do
            if d:IsA("VehicleSeat") and not d.Occupant then local dd = (d.Position - r.Position).Magnitude if not bd or dd < bd then best, bd = d, dd end end
        end
        if not best then notify(__T["No free vehicle"]) return end
        G.unseat(h)
        r.CFrame = best.CFrame + Vector3.new(0, 2, 0)
        task.wait(0.2)
        pcall(function() best:Sit(h) end)
    end })
    local function key(k) return UserInputService:IsKeyDown(k) and not UserInputService:GetFocusedTextBox() end
    local FC = { on = false, yaw = 0, pitch = 0 }
    local CAS = game:GetService("ContextActionService")
    local function sink(onf) if onf then CAS:BindActionAtPriority("CWFreeCam", function() return Enum.ContextActionResult.Sink end, false, 3000, Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Space, Enum.KeyCode.E, Enum.KeyCode.Q) else pcall(function() CAS:UnbindAction("CWFreeCam") end) end end
    MV:AddToggle("fn_freecam", { Text = __T["Free Cam"], Default = false, Tooltip = __T["WASD/E/Q move, right-click drag to look, Shift fast"], Callback = function(v)
        local cam = Workspace.CurrentCamera
        if v then
            FC.prevType, FC.prevSubject = cam.CameraType, cam.CameraSubject
            FC.cf = cam.CFrame
            local x, y = cam.CFrame:ToOrientation()
            FC.pitch, FC.yaw, FC.on = x, y, true
            cam.CameraType = Enum.CameraType.Scriptable
            sink(true)
        elseif FC.on then
            sink(false)
            FC.on = false
            cam.CameraType = FC.prevType or Enum.CameraType.Custom
            local h = G.hum() if h then cam.CameraSubject = h end
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        end
    end }):AddKeyPicker("fn_freecam_key", { Default = "P", Mode = "Toggle", Text = __T["Free Cam"], SyncToggleState = true })
    track(RunService.RenderStepped:Connect(function(dt)
        if not FC.on then return end
        local cam = Workspace.CurrentCamera
        if cam.CameraType ~= Enum.CameraType.Scriptable then cam.CameraType = Enum.CameraType.Scriptable end
        if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
            local d = UserInputService:GetMouseDelta()
            FC.yaw -= d.X * 0.004 FC.pitch = math.clamp(FC.pitch - d.Y * 0.004, -1.5, 1.5)
        else UserInputService.MouseBehavior = Enum.MouseBehavior.Default end
        local rot = CFrame.fromOrientation(FC.pitch, FC.yaw, 0)
        local mv = Vector3.zero
        if key(Enum.KeyCode.W) then mv += Vector3.new(0, 0, -1) end
        if key(Enum.KeyCode.S) then mv += Vector3.new(0, 0, 1) end
        if key(Enum.KeyCode.A) then mv += Vector3.new(-1, 0, 0) end
        if key(Enum.KeyCode.D) then mv += Vector3.new(1, 0, 0) end
        if key(Enum.KeyCode.E) then mv += Vector3.new(0, 1, 0) end
        if key(Enum.KeyCode.Q) then mv += Vector3.new(0, -1, 0) end
        local sp = key(Enum.KeyCode.LeftShift) and 160 or 50
        local pos = FC.cf.Position + (mv.Magnitude > 0 and rot:VectorToWorldSpace(mv.Unit) * sp * dt or Vector3.zero)
        FC.cf = CFrame.new(pos) * rot
        cam.CFrame = FC.cf
    end))
    onClean(function() sink(false) if FC.on then FC.on = false local cam = Workspace.CurrentCamera cam.CameraType = Enum.CameraType.Custom local h = G.hum() if h then cam.CameraSubject = h end end end)
    local VS = Tab:AddRightGroupbox(__T["Visuals"], "sun")
    local LO = {}
    VS:AddToggle("fn_bright", { Text = __T["Fullbright"], Default = false, Callback = function(v)
        if v then LO.a, LO.b, LO.o, LO.f, LO.s = Lighting.Ambient, Lighting.Brightness, Lighting.OutdoorAmbient, Lighting.FogEnd, Lighting.GlobalShadows
        elseif LO.a then pcall(function() Lighting.Ambient, Lighting.Brightness, Lighting.OutdoorAmbient, Lighting.FogEnd, Lighting.GlobalShadows = LO.a, LO.b, LO.o, LO.f, LO.s end) end
    end })
    VS:AddToggle("fn_noshake", { Text = __T["No Camera Shake"], Default = false, Callback = function(v) pcall(function() G.R.RequestSetting:FireServer("CameraShake", not v) end) end })
    VS:AddToggle("fn_noweather", { Text = __T["No Weather Effects"], Default = false, Callback = function(v) pcall(function() G.R.RequestSetting:FireServer("WeatherParticles", not v) end) end })
    track(RunService.RenderStepped:Connect(function()
        if on("fn_bright") then Lighting.Ambient, Lighting.OutdoorAmbient, Lighting.Brightness, Lighting.FogEnd, Lighting.GlobalShadows = Color3.fromRGB(170, 170, 170), Color3.fromRGB(170, 170, 170), 2, 1e5, false end
    end))
    onClean(function() if LO.a and Toggles.fn_bright and Toggles.fn_bright.Value then pcall(function() Lighting.Ambient, Lighting.Brightness, Lighting.OutdoorAmbient, Lighting.FogEnd, Lighting.GlobalShadows = LO.a, LO.b, LO.o, LO.f, LO.s end) end end)
    local FLY = {}
    track(RunService.Heartbeat:Connect(function(dt)
        local r, h = G.root(), G.hum()
        if not (r and h) then FLY.v, FLY.p = nil, nil return end
        if on("fn_ws") and h.WalkSpeed > 0 then h.WalkSpeed = val("fn_ws_v", 32) end
        if on("fn_jp") then h.UseJumpPower = true h.JumpPower = val("fn_jp_v", 80) end
        local seat = h.SeatPart
        if seat and seat:IsA("VehicleSeat") then
            local veh = seat:FindFirstAncestorOfClass("Model")
            while veh and not veh:FindFirstChild("Body") and veh.Parent and veh.Parent:IsA("Model") do veh = veh.Parent end
            local body = veh and veh:FindFirstChild("Body")
            if body and on("fn_vfly") then
                local cam = Workspace.CurrentCamera.CFrame
                local flat = Vector3.new(cam.LookVector.X, 0, cam.LookVector.Z)
                flat = flat.Magnitude > 0.1 and flat.Unit or body.CFrame.LookVector
                local thr, str = seat.ThrottleFloat, seat.SteerFloat
                if thr == 0 then thr = (key(Enum.KeyCode.W) and 1 or 0) - (key(Enum.KeyCode.S) and 1 or 0) end
                if str == 0 then str = (key(Enum.KeyCode.D) and 1 or 0) - (key(Enum.KeyCode.A) and 1 or 0) end
                local dir = flat * thr + Vector3.new(flat.Z, 0, -flat.X) * -str
                if key(Enum.KeyCode.E) or key(Enum.KeyCode.Space) then dir += Vector3.new(0, 1, 0) end
                if key(Enum.KeyCode.Q) or key(Enum.KeyCode.LeftControl) then dir -= Vector3.new(0, 1, 0) end
                FLY.v = FLY.v or body.Position
                if dir.Magnitude > 0 then
                    local nv = FLY.v + dir.Unit * val("fn_vfly_s", 90) * dt
                    if nv.Y < FLY.v.Y then local rp = RaycastParams.new() rp.FilterType = Enum.RaycastFilterType.Exclude rp.FilterDescendantsInstances = { veh, lp.Character } local hit = Workspace:Raycast(nv + Vector3.new(0, 3, 0), Vector3.new(0, -8, 0), rp) if hit then nv = Vector3.new(nv.X, math.max(nv.Y, hit.Position.Y + 3), nv.Z) end end
                    FLY.v = nv
                end
                body.CFrame = CFrame.lookAt(FLY.v, FLY.v + flat)
                body.AssemblyLinearVelocity = Vector3.zero
                body.AssemblyAngularVelocity = Vector3.zero
            elseif body and on("fn_vspeed") and math.abs(seat.ThrottleFloat) > 0.1 then
                local look = body.CFrame.LookVector
                local v = body.AssemblyLinearVelocity
                local fwd = v:Dot(look)
                local want = val("fn_vspeed_v", 120) * seat.ThrottleFloat
                if math.abs(fwd) < math.abs(want) then body.AssemblyLinearVelocity = v + look * (want - fwd) * 0.08 end
            end
        elseif on("fn_fly") then
            FLY.v = nil
            local cam = Workspace.CurrentCamera.CFrame
            local dir = Vector3.zero
            if key(Enum.KeyCode.W) then dir += cam.LookVector end
            if key(Enum.KeyCode.S) then dir -= cam.LookVector end
            if key(Enum.KeyCode.D) then dir += cam.RightVector end
            if key(Enum.KeyCode.A) then dir -= cam.RightVector end
            if key(Enum.KeyCode.Space) then dir += Vector3.new(0, 1, 0) end
            if key(Enum.KeyCode.LeftControl) then dir -= Vector3.new(0, 1, 0) end
            FLY.p = FLY.p or r.Position
            if dir.Magnitude > 0 then FLY.p += dir.Unit * val("fn_fly_s", 60) * dt end
            local flat = Vector3.new(cam.LookVector.X, 0, cam.LookVector.Z)
            r.CFrame = flat.Magnitude > 0.1 and CFrame.lookAt(FLY.p, FLY.p + flat) or CFrame.new(FLY.p)
            r.AssemblyLinearVelocity = Vector3.zero
        else
            FLY.v, FLY.p = nil, nil
        end
        if not (seat and seat:IsA("VehicleSeat") and on("fn_vfly")) then FLY.v = nil end
        if not on("fn_fly") or (seat and seat:IsA("VehicleSeat")) then FLY.p = nil end
    end))
    track(RunService.Stepped:Connect(function()
        if on("fn_noclip") or on("fn_fly") then local c = lp.Character if c then for _, p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end end end end
    end))
    track(UserInputService.JumpRequest:Connect(function() if on("fn_infjump") then local h = G.hum() if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end end end))
    track(UserInputService.InputBegan:Connect(function(i, gp)
        if gp or not on("fn_clicktp") or i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        if not (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)) then return end
        local m = lp:GetMouse() local r, h = G.root(), G.hum()
        if m and m.Hit and r then G.unseat(h) r.CFrame = CFrame.new(m.Hit.Position + Vector3.new(0, 3, 0)) end
    end))
end)
section(__T["Farm"], function()
    local Tab = Window:AddTab(__T["Extras"], "gift")
    local FB = Tab:AddLeftGroupbox(__T["Rewards"], "gift")
    FB:AddToggle("fm_missions", { Text = __T["Auto Claim Missions"], Default = true })
    FB:AddButton({ Text = __T["Claim Missions Now"], Func = function() task.spawn(function() local n = FM.claim() notify(n > 0 and (__T["Claimed "] .. n .. __T[" missions"]) or __T["Nothing to claim"]) end) end })
    FB:AddToggle("fm_streak", { Text = __T["Auto Restore Streak"], Default = false, Tooltip = __T["Pays with credits only"] })
    FB:AddSlider("fm_streak_max", { Text = __T["Max Price"], Default = 1000, Min = 100, Max = 10000, Rounding = 0 })
    FB:AddToggle("fm_afk", { Text = __T["Anti AFK"], Default = true })
    track(lp.Idled:Connect(function() if on("fm_afk") then pcall(function() VirtualUser:CaptureController() VirtualUser:ClickButton2(Vector2.new()) end) end end))
    local SV = Tab:AddRightGroupbox(__T["Server"], "server")
    UI.sv = SV:AddLabel("", true)
    local function hop(maxP)
        local cursor, best = "", nil
        for _ = 1, 5 do
            local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100" .. (cursor ~= "" and ("&cursor=" .. cursor) or "")
            local ok, body = pcall(function() return game:HttpGet(url) end)
            local okj, data = pcall(function() return HttpService:JSONDecode(body) end)
            if not (ok and okj and type(data) == "table" and type(data.data) == "table") then break end
            for _, sv in ipairs(data.data) do
                local n = tonumber(sv.playing) or 0
                if sv.id ~= game.JobId and n >= 1 and n <= maxP and (not best or n < best.playing) then best = { id = sv.id, playing = n } end
            end
            if best or not data.nextPageCursor then break end
            cursor = data.nextPageCursor
        end
        return best
    end
    SV:AddButton({ Text = __T["Hop To Small Server (1-2)"], Func = function()
        setText(UI.sv, __T["Searching..."])
        task.spawn(function()
            local best = hop(2)
            if not best then setText(UI.sv, __T["No 1-2 player server found"]) return end
            setText(UI.sv, __T["Joining a "] .. best.playing .. __T[" player server..."])
            pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, best.id, lp) end)
        end)
    end })
    SV:AddButton({ Text = __T["Rejoin"], Func = function() pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp) end) end })
    local SB = Tab:AddRightGroupbox(__T["Session"], "list")
    UI.f1 = SB:AddLabel("", true)
    UI.f2 = SB:AddLabel("", true)
    task.delay(6, function() if RUNNING and on("fm_missions") then FM.claim() end end)
    local EB = Tab:AddLeftGroupbox("Players", "users")
    EB:AddToggle("es_players", { Text = __T["Player ESP"], Default = false })
    EB:AddToggle("es_staff", { Text = __T["Staff Alert"], Default = true, Tooltip = __T["Warns when a game admin is here"] })
    local VB = Tab:AddRightGroupbox(__T["Viewers"], "scan-eye")
    VB:AddToggle("vw_alert", { Text = __T["Viewer Alert"], Default = true, Tooltip = __T["Tells you when someone spectates you"] })
    UI.vw = VB:AddLabel("", true)
    local EP = {}
    local folder = Instance.new("Folder")
    pcall(function() folder.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
    if not folder.Parent then folder.Parent = lp:WaitForChild("PlayerGui") end
    onClean(function() pcall(function() folder:Destroy() end) end)
    local warned = {}
    task.spawn(function()
        while RUNNING do
            local r = G.root()
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= lp then
                    local staff = p:GetAttribute("CmdrAdmin") == true or p:GetAttribute("Hidden") == true
                    if staff and on("es_staff") and not warned[p] then warned[p] = true notify(__T["Staff in server: "] .. p.DisplayName) end
                    local head = p.Character and p.Character:FindFirstChild("Head")
                    local e = EP[p]
                    if on("es_players") and head then
                        if not e then
                            local bb = Instance.new("BillboardGui")
                            bb.AlwaysOnTop, bb.Size, bb.StudsOffset = true, UDim2.fromOffset(140, 30), Vector3.new(0, 2.5, 0)
                            local tl = Instance.new("TextLabel")
                            tl.BackgroundTransparency, tl.Size, tl.Font, tl.TextSize, tl.TextStrokeTransparency = 1, UDim2.fromScale(1, 1), Enum.Font.GothamBold, 12, 0.4
                            tl.Parent = bb bb.Parent = folder
                            e = { bb = bb, tl = tl } EP[p] = e
                        end
                        e.bb.Adornee = head
                        local d = r and math.floor((head.Position - r.Position).Magnitude) or 0
                        e.tl.Text = p.DisplayName .. "  " .. d .. "m" .. (staff and __T["  [STAFF]"] or "")
                        e.tl.TextColor3 = staff and Color3.fromRGB(255, 70, 70) or (p:GetAttribute("InRound") and Color3.fromRGB(235, 235, 235) or Color3.fromRGB(150, 150, 160))
                        e.bb.Enabled = true
                    elseif e then e.bb.Enabled = false end
                end
            end
            for p, e in pairs(EP) do if not p.Parent then pcall(function() e.bb:Destroy() end) EP[p] = nil end end
            local n = lp:GetAttribute("Spectators") or 0
            local pos = VW.possible()
            setText(UI.vw, n > 0 and (n .. __T[" watching you"] .. (VW.who ~= "" and (" (" .. VW.who .. ")") or "")) or (__T["Nobody watching"] .. (#pos > 0 and (__T["\nCould watch: "] .. table.concat(pos, ", ", 1, math.min(#pos, 6))) or "")))
            task.wait(0.5)
        end
    end)
end)
task.spawn(function()
    while RUNNING do
        S.credits0 = S.credits0 or G.credits()
        local ph = tostring(G.phase() or "")
        local dis = tostring(G.RS:GetAttribute("DisasterId") or "")
        local left = math.max(0, math.floor(G.left()))
        setText(UI.s1, ph .. (dis ~= "" and (" · " .. dis) or "") .. " · " .. left .. "s")
        setText(UI.s0, string.format(__T["Streak %s (best %s) · %s credits"], tostring(lp:GetAttribute("Streak") or 0), tostring(lp:GetAttribute("BestStreak") or 0), tostring(G.credits())))
        local gt = G.DS:GetAttribute("GoalSafeText") or ""
        setText(UI.s2, gt ~= "" and (__T["Goal: "] .. gt) or __T["Goal: -"])
        local gs, hs = lp:GetAttribute("GoalSafe"), lp:GetAttribute("HazardState")
        setText(UI.s3, G.inRound() and (__T["Safe: "] .. (gs == true and __T["YES"] or (gs == false and __T["NO"] or "-")) .. (hs and (" · " .. tostring(hs)) or "")) or __T["Not in round"])
        setText(UI.s4, on("sv_auto") and (__T["Doing: "] .. S.task) or __T["Auto Survive off"])
        local n = lp:GetAttribute("Spectators") or 0
        setText(UI.s5, n > 0 and (__T["Viewers: "] .. n .. (VW.who ~= "" and (" (" .. VW.who .. ")") or "")) or "")
        local hint = dis ~= "" and G.hint(dis) or ""
        setText(UI.hint, hint ~= "" and hint or __T["Shows the tip for the current disaster."])
        local m = math.max(1, (os.clock() - S.t0) / 60)
        local gained = G.credits() - S.credits0
        setText(UI.f1, string.format(__T["Credits +%d (%d/h)"], gained, math.floor(gained / m * 60)))
        setText(UI.f2, string.format(__T["Rounds %d · Survived %d · Streak %s"], S.rounds, S.survived, tostring(lp:GetAttribute("Streak") or 0)))
        task.wait(0.5)
    end
end)
section(__T["Streamer"], function()
    local Tab = Window:AddTab(__T["Streamer"], "eye")
    local ST = { HideMe = false, FakeName = "Player", HideOthers = false, HideAvatars = false, HidePlayerList = false, HideChat = false }
    ST.conns, ST.objConns, ST.orig, ST.written, ST.alias = {}, setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    ST.aliasN, ST.rev = 0, {}
    local rules, ids = {}, {}
    local function aliasFor(plr)
        if plr == lp then return (ST.FakeName ~= "" and ST.FakeName) or "Player" end
        if not ST.alias[plr] then ST.aliasN = ST.aliasN + 1 ST.alias[plr] = "Player " .. ST.aliasN end
        return ST.alias[plr]
    end
    local function active() return ST.HideMe or ST.HideOthers or ST.HideAvatars end
    local function esc(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end
    local ZW = utf8.char(0x200B)
    local function unfix(t)
        if not t:find(ZW, 1, true) then return t end
        local keys = {} for k in pairs(ST.rev) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return #a > #b end)
        for _, k in ipairs(keys) do if t:find(k, 1, true) then t = t:gsub(esc(k), (ST.rev[k]:gsub("%%", "%%%%"))) end end
        return (t:gsub(ZW, ""))
    end
    local function rebuild()
        rules, ids = {}, {}
        local seen = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            local mine = plr == lp
            if (mine and ST.HideMe) or (not mine and ST.HideOthers) then
                local a = aliasFor(plr)
                for i, n in ipairs({ plr.DisplayName, plr.Name }) do
                    if type(n) == "string" and #n >= 3 and not seen[n] then
                        seen[n] = true
                        local rep = a .. ZW .. (i == 2 and ZW or "")
                        rules[#rules + 1] = { pat = "%f[%w_]" .. esc(n) .. "%f[^%w_]", plain = n, rep = rep }
                        ST.rev[rep] = n
                    end
                end
            end
            if ST.HideAvatars and (mine or ST.HideOthers) then ids[#ids + 1] = tostring(plr.UserId) end
        end
        table.sort(rules, function(a, b) return #a.plain > #b.plain end)
    end
    local function fixText(t) local o = t for _, r in ipairs(rules) do if o:find(r.plain, 1, true) then o = o:gsub(r.pat, (r.rep:gsub("%%", "%%%%"))) end end return o end
    local function fixImg(img) for _, id in ipairs(ids) do if img:find("=" .. id, 1, true) then return "" end end return img end
    local function propOf(d) if d:IsA("TextLabel") or d:IsA("TextButton") then return "Text" elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then return "Image" end end
    local function process(d)
        local p = propOf(d) if not p then return end
        local cur = d[p]
        if ST.written[d] ~= nil and cur == ST.written[d] then return end
        local fixed = p == "Text" and fixText(cur) or fixImg(cur)
        if fixed ~= cur then ST.orig[d], ST.written[d] = cur, fixed d[p] = fixed else ST.orig[d], ST.written[d] = nil, nil end
    end
    local function watch(d) if ST.objConns[d] then return end local p = propOf(d) if not p then return end ST.objConns[d] = d:GetPropertyChangedSignal(p):Connect(function() if active() then pcall(process, d) end end) pcall(process, d) end
    local function walk(inst, d) if d > 60 then return end local ok, k = pcall(inst.GetChildren, inst) if not ok then return end for _, c in ipairs(k) do pcall(watch, c) walk(c, d + 1) end end
    local function setHum(plr) local h = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then local hide = (plr == lp and ST.HideMe) or (plr ~= lp and ST.HideOthers) pcall(function() h.DisplayName = hide and aliasFor(plr) or plr.DisplayName end) end end
    local function startWatch()
        if ST.watching then return end
        ST.watching = true
        local roots = { lp:WaitForChild("PlayerGui") }
        pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
        pcall(function() local h = gethui and gethui() if typeof(h) == "Instance" then roots[#roots + 1] = h end end)
        pcall(function() roots[#roots + 1] = Workspace end)
        for i, rt in ipairs(roots) do walk(rt, 0) ST.conns["a" .. i] = rt.DescendantAdded:Connect(function(d) if propOf(d) then task.defer(function() if active() and d.Parent then watch(d) end end) end end) end
    end
    local function restoreAll()
        for d in pairs(ST.objConns) do pcall(function() if propOf(d) == "Text" then local u = unfix(d.Text) if u ~= d.Text then d.Text = u end elseif propOf(d) == "Image" and ST.orig[d] then d.Image = ST.orig[d] end end) end
        ST.written, ST.orig = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    end
    local function refresh()
        rebuild()
        for _, p in ipairs(Players:GetPlayers()) do setHum(p) end
        restoreAll()
        if active() then if ST.watching then for d in pairs(ST.objConns) do pcall(process, d) end else startWatch() end end
    end
    local function applyCore()
        pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, not ST.HidePlayerList) end)
        if ST.HideChat then pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, false) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = false end)
        else pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, true) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = true end) end
    end
    track(Players.PlayerAdded:Connect(function() if active() then refresh() end end))
    local B = Tab:AddLeftGroupbox(__T["Hide Identity"], "user")
    B:AddToggle("st_me", { Text = __T["Hide My Name"], Default = false, Callback = function(v) ST.HideMe = v refresh() end })
    B:AddInput("st_name", { Text = __T["Fake Name"], Default = "Player", Finished = true, Callback = function(v) v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "") ST.FakeName = (v ~= "" and v:sub(1, 20)) or "Player" refresh() end })
    B:AddToggle("st_others", { Text = __T["Hide Other Names"], Default = false, Callback = function(v) ST.HideOthers = v refresh() end })
    B:AddToggle("st_av", { Text = __T["Hide Avatars"], Default = false, Callback = function(v) ST.HideAvatars = v refresh() end })
    local B2 = Tab:AddRightGroupbox(__T["Hide Roblox UI"], "monitor")
    B2:AddToggle("st_list", { Text = __T["Hide Player List"], Default = false, Callback = function(v) ST.HidePlayerList = v applyCore() end })
    B2:AddToggle("st_chat", { Text = __T["Hide Chat"], Default = false, Callback = function(v) ST.HideChat = v applyCore() end })
    onClean(function() ST.HideMe, ST.HideOthers, ST.HideAvatars, ST.HidePlayerList, ST.HideChat = false, false, false, false, false pcall(refresh) pcall(applyCore) for _, c in pairs(ST.conns) do pcall(function() c:Disconnect() end) end end)
end)
section(__T["Settings"], function()
    local Tab = Window:AddTab(__T["Settings"], "settings")
    local Menu = Tab:AddLeftGroupbox(__T["Menu"], "menu")
    Menu:AddLabel(__T["Menu Key"]):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = __T["Menu Key"] })
